        ('hiv_plhiv_advanced_hiv_active_care', 'metric', 'PLHIV with advanced HIV in active care', 'People living with HIV ever diagnosed with advanced HIV disease who are in active care in the reporting month.', 'Distinct HIV-cohort patients with an On-ART or Refused-treatment HIV Visit in the reporting month who ever had a CD4 result at or below 200, or WHO stage 3/4 at that visit, or age 5 or under at that visit', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('hiv_plhiv_ever_started_art', 'metric', 'PLHIV ever started on ART', 'People living with HIV who have ever started ART, as of the reporting month end.', 'Distinct HIV-cohort patients with at least one HIV Visit up to month end whose ART status is Initiated ART, On ART, Transferred out, or Refused (stopped) treatment (cumulative)', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('hiv_plhiv_tested_viral_load', 'metric', 'PLHIV tested for viral load', 'People living with HIV with a viral load test in the trailing 12 months.', 'Distinct patients with a published viral load result in the 12 months up to the reporting month end', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('hiv_plhiv_virologically_suppressed', 'metric', 'PLHIV virologically suppressed', 'People living with HIV virologically suppressed on their most recent viral load.', 'Distinct patients from the VL-tested cohort whose most recent viral load in the 12-month window is numerically below 1000 copies/mL', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('htn_bp_controlled', 'metric', 'Hypertension patients with controlled BP', 'Hypertension patients with a controlled blood-pressure measurement in the reporting month.', 'Distinct hypertension patients with a controlled blood-pressure measurement in the reporting month', null, 'tamanu', 'MSF', null, 'MSF NCD program operational definition', 'count', 'patient', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/ncd-indicators.md'),
        ('htn_bp_measured', 'metric', 'Hypertension patients with BP measured', 'Hypertension patients with at least one blood-pressure measurement in the reporting month.', 'Distinct hypertension patients with at least one recorded blood-pressure measurement in the reporting month', null, 'tamanu', 'MSF', null, 'MSF NCD program operational definition', 'count', 'patient', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/ncd-indicators.md'),
        ('hypertension_followup', 'metric', 'MSF Kule OPD — Hypertension — follow-up consultations', 'MSF Kule chronic-care OPD report: follow-up outpatient consultations for Hypertension, weekly by sex and age band.', 'NCD-area follow-up consultations whose visit-form primary diagnosis (kulencdvisit002) maps to Hypertension.', null, 'tamanu', 'MSF', null, 'MSF Kule chronic-care OPD consultations report operational definition', 'count', 'encounter', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__opd_indicators.md'),
        ('inpatient_admission', 'metric', 'Inpatient admissions', 'Hospital admissions, from becoming an inpatient to discharge from hospital. One row per admission.', 'Encounters with a segment whose first recorded instance is typed as an inpatient visit, counted on the date that segment began', null, 'tamanu', 'AIHW', '695137', 'Admission/discharge dates follow AIHW METeOR "Episode of admitted patient care" admission date (695137) and separation date (270025). AIHW''s admission mode (269976) and mode of separation (722644) are fixed, small vocabularies with no guaranteed mapping to Tamanu''s deployment-configured reference data, so admission_source and discharge_disposition are carried as-recorded (BES composition) rather than implementations of those coded vocabularies -- is_admitted_via_emergency covers the one admission-mode category Tamanu can derive unambiguously. Pending alignment with the deploying country''s national HMIS definition.', 'count', 'visit', 'facility_id,sex,admission_ward_id,admission_source,is_admitted_via_emergency,principal_diagnosis__icd10_chapter,discharge_disposition,is_readmission_within_30_days', null, 'bes-maui', 'draft', 'specs/dbt-model/metric__inpatient_admission.md'),
        ('low_apgar_5min', 'metric', 'Low Apgar score at 5 minutes', 'Births with an Apgar score below 7 at 5 minutes. Numerator only -- rate is formed downstream against the birth metric_id.', 'Births with apgar_score_five_minutes recorded and less than 7', null, 'tamanu', 'BES', null, 'Threshold follows WHO Newborn Health guidance''s low Apgar score at 5 minutes, a marker of neonatal distress. No METeOR-style registered code exists for it, unlike the AIHW-anchored ed_visit concepts, and it is not a WHO 100 Core Health Indicators entry -- a BES composition over a clinical convention, not an implementation of a named indicator. Numerator only, same reasoning as low_birth_weight.', 'count', 'patient', 'facility_id,sex,birth_delivery_type,attendant_at_birth,registered_birth_place,birth_type', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__birth.md'),
        ('low_birth_weight', 'metric', 'Low birth weight', 'Births weighing less than 2.5 kg. Numerator only -- rate is formed downstream against the birth metric_id.', 'Births with birth_weight recorded and less than 2.5 kg', null, 'tamanu', 'WHO_CORE_100', null, 'Low birth weight prevalence is a WHO Global Reference List of 100 Core Health Indicators entry; the threshold follows the WHO/UNICEF joint low-birthweight estimates -- born weighing less than 2,500 g. Numerator only -- Tamanu holds no population denominator for a rate, and a rate is never stored per D5 "Rate scale". A consumer computing low_birth_weight / birth assumes weight is recorded uniformly across births; see the spec''s consumer guidance.', 'count', 'patient', 'facility_id,sex,birth_delivery_type,attendant_at_birth,registered_birth_place,birth_type', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__birth.md'),
        ('medication_side_effects', 'metric', 'Patients with medication side effects', 'Distinct patients with a documented medication side effect on a Psychiatry Follow Up form in the reporting month.', 'Distinct patients with a non-empty answer to any of the three side-effect questions (extra-pyramidal/metabolic/other) on a Psychiatry Follow Up form in the reporting month', null, 'tamanu', 'MSF', null, 'MSF Mental Health Sessions (Psychiatry and mhGAP) program operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__mental_health_sessions.md'),
        ('opd_procedure', 'metric', 'OPD procedures', 'Clinical procedures performed during an outpatient (OMOP 9202) encounter. One row per procedure.', 'Recorded procedures whose encounter carries OMOP visit concept 9202 (Outpatient Visit), counted on the date performed', null, 'tamanu', 'BES', null, 'A count of recorded procedures scoped to the outpatient setting. No external body registers a single procedure-count indicator -- procedure classifications (e.g. ICD-10-PCS, CPT) code what a procedure is, not how a deployment should count procedure activity, and deployments differ in what they code procedures with. This metric emits the procedure as recorded and leaves any grouping to the consumer, the same approach metric__procedure takes. Pending alignment with the deploying country''s national HMIS definition.', 'count', 'procedure', 'facility_id,sex,procedure,procedure_code,is_completed', null, 'bes-maui', 'draft', 'specs/dbt-model/metric__opd_procedure.md'),
        ('opd_visit', 'metric', 'OPD visits', 'Outpatient department visits. One row per visit, from encounters whose first recorded segment is a clinic, vaccination or imaging phase.', 'Encounters whose first recorded segment carries OMOP visit concept 9202 (Outpatient Visit), counted on the visit date', null, 'tamanu', 'AIHW', '400604', 'Visit concept follows the AIHW METeOR object class "Non-admitted patient service event" (METeOR 400604), the closest AIHW concept anchor for a non-admitted clinic/vaccination/imaging encounter. AIHW registers no plain OPD attendance-count indicator -- its non-admitted reporting is built around the Tier 2 Non-Admitted Services Classification and per-clinic activity counts, not a single cross-clinic count -- so this is a BES composition over the AIHW concept, not an implementation of an AIHW indicator. "Occasion of service" (METeOR 270511) was considered and rejected as the anchor: it is scoped to a narrower residual clinic category, not the general OPD population this metric covers. Pending alignment with the deploying country''s national HMIS definition.', 'count', 'visit', 'facility_id,location_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__outpatient_visit.md'),
        ('other_chronic_followup', 'metric', 'MSF Kule OPD — Other chronic diseases — follow-up consultations', 'MSF Kule chronic-care OPD report: follow-up outpatient consultations for Other chronic diseases, weekly by sex and age band.', 'NCD-area follow-up consultations whose visit-form primary diagnosis (kulencdvisit002) maps to Other chronic diseases.', null, 'tamanu', 'MSF', null, 'MSF Kule chronic-care OPD consultations report operational definition', 'count', 'encounter', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__opd_indicators.md'),
        ('patients_active', 'metric', 'Active NCD patients', 'Patients with an active NCD registration as of the reporting month.', 'Distinct patients with an active NCD registration as of month end (active before month end and exit not yet recorded)', null, 'tamanu', 'MSF', null, 'MSF NCD program operational definition', 'count', 'patient', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/ncd-indicators.md'),
        ('patients_new', 'metric', 'Newly enrolled NCD patients', 'Patients whose NCD registration first transitioned to ncdactive during the reporting month and were still active at month end.', 'Distinct patients whose NCD registration first became active in the reporting month and who were still active at month end', null, 'tamanu', 'MSF', null, 'MSF NCD program operational definition', 'count', 'patient', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/ncd-indicators.md'),
        ('pmtct_hiv_exposed_babies_born_alive', 'metric', 'HIV-exposed babies born alive', 'HIV-exposed infants born alive to mothers who delivered in an MSF facility.', 'Distinct exposed-child patients with an Exposed Child initial-visit form in the reporting month whose mother (via mother_id) delivered in an MSF facility, with the initial visit within 12 weeks of that delivery', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('pmtct_hiv_exposed_newborns_pep_72h', 'metric', 'HIV-exposed newborns started on PEP within 72h', 'HIV-exposed newborns who started post-exposure prophylaxis within 72 hours of birth.', 'Distinct exposed-child patients with an initial-visit form in the reporting month recording PEP started within 72h, whose mother (via mother_id) delivered in an MSF facility', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('pmtct_hiv_exposed_pcr_dna_done', 'metric', 'HIV-exposed infants with initial DNA PCR done', 'HIV-exposed infants with an initial DNA PCR test performed.', 'Distinct exposed infants with a published initial DNA PCR lab result in the reporting month whose mother (via mother_id) delivered in an MSF facility', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('pmtct_hiv_positive_delivering', 'metric', 'HIV+ women delivering in an MSF facility', 'HIV-positive women who delivered in an MSF facility during the reporting month.', 'Distinct women with a PMTCT Delivery form marked delivery-in-MSF-facility = Yes, bucketed by the recorded delivery date falling in the reporting month', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('pmtct_hiv_positive_delivering_on_art', 'metric', 'HIV+ women delivering on ART', 'HIV-positive women delivering in an MSF facility who were on ART.', 'Distinct women from the delivering-in-MSF cohort who were already on ART at ANC enrolment, or initiated ART at an ANC visit before the delivery date', null, 'tamanu', 'MSF', null, 'MSF OCA Standard Indicators Report (HIV/TB/PMTCT) operational definition', 'count', 'patient', 'facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__hivtb_standard_indicators.md'),
        ('preterm_birth', 'metric', 'Preterm birth', 'Births before 37 completed weeks of gestation. Numerator only -- rate is formed downstream against the birth metric_id.', 'Births with gestational_age_estimate recorded and less than 37 completed weeks', null, 'tamanu', 'BES', null, 'Threshold follows the WHO preterm birth definition -- born before 37 completed weeks of gestation -- but preterm birth rate is not itself an entry in the WHO 100 Core Health Indicators list, so the count is a BES composition over the WHO threshold rather than an implementation of a registered indicator. Numerator only, same reasoning as low_birth_weight.', 'count', 'patient', 'facility_id,sex,birth_delivery_type,attendant_at_birth,registered_birth_place,birth_type', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__birth.md'),
        ('procedure', 'metric', 'Procedures', 'Clinical procedures performed on a patient, in any encounter setting. One row per procedure.', 'Recorded procedures, counted on the date performed', null, 'tamanu', 'BES', null, 'A count of recorded procedures, which no external body registers as a single indicator -- procedure classifications (e.g. ICD-10-PCS, CPT) code what a procedure is, not how a deployment should count procedure activity, and deployments differ in what they code procedures with. This metric emits the procedure as recorded and leaves any grouping to the consumer, the same approach encounter_diagnosis takes for diagnoses. Pending alignment with the deploying country''s national HMIS definition.', 'count', 'procedure', 'facility_id,encounter_type,sex,procedure,procedure_code,is_completed', null, 'bes-maui', 'draft', null),
        ('program_registry_enrolment', 'metric', 'Program registry enrolments', 'Patient enrolments in a Tamanu program registry. One row per enrolment, spanning registration to the end of the registration, disaggregated by registry and by the patient''s clinical status within it.', 'Patient program registrations, excluding those recorded in error, counted at the registration datetime. The row is a span, so a consumer may instead count enrolments open during a period -- period_start before its end and period_end null or after its start -- which is a different number over the same rows. An enrolment closed before Tamanu 2.33.0 carries no recorded end and so reads as open, which makes registration_status the column answering whether a patient exited and period_end the column answering when a dated exit happened', null, 'tamanu', 'BES', null, 'A program registry is Tamanu''s own construct for following a patient through a long-running care programme, so the enrolment is defined by the deployment''s registry configuration rather than by an external standard. The measure is registry-agnostic on purpose: the same definition serves an HIV cascade, a TB register and an NCD register, because the programme-specific part is the clinical status list, which is a disaggregation rather than a definition. Cascade positions and retention are both derived by the consumer -- position by grouping on clinical_status_code, retention from the enrolment boundaries -- so a programme does not need its own metric to be reportable. Where a standards body defines a programme indicator over the same population (WHO HIV treatment coverage, an MSF standard indicator), that indicator is registered separately and this metric is not a substitute for it.', 'count', 'episode', 'registry_code,clinical_status_code,registration_status,currently_at_type,currently_at_id,episode_end_source,facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__program_registry_enrolment.md'),
        ('psych_adjustment_followup', 'metric', 'MSF Kule OPD — Adjustment disorder — follow-up consultations', 'MSF Kule chronic-care OPD report: follow-up outpatient consultations for Adjustment disorder, weekly by sex and age band.', 'Psychiatry-area consultations (subsequent in the area) whose baseline primary diagnosis (psychbaseline040) maps to Adjustment disorder.', null, 'tamanu', 'MSF', null, 'MSF Kule chronic-care OPD consultations report operational definition', 'count', 'encounter', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__opd_indicators.md'),
        ('psych_adjustment_new', 'metric', 'MSF Kule OPD — Adjustment disorder — new consultations', 'MSF Kule chronic-care OPD report: new (first) outpatient consultations for Adjustment disorder, weekly by sex and age band.', 'Psychiatry-area consultations (first in the area) whose baseline primary diagnosis (psychbaseline040) maps to Adjustment disorder.', null, 'tamanu', 'MSF', null, 'MSF Kule chronic-care OPD consultations report operational definition', 'count', 'encounter', 'age_group,sex,facility_id', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__opd_indicators.md'),
