        ('who_dak_hiv_art_initiated', 'metric', 'New ART patients (ART.4)', 'People living with HIV who initiated antiretroviral therapy during the reporting month.', 'COUNT of clients recorded as on ART whose ART start date falls in the reporting period. Counted in the month treatment began, so a form recorded late still counts in the right month', null, 'tamanu', 'WHO_SMART_HIV', 'ART.4', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.30 (ART.4, "New ART patients"), whose denominator Annex C gives as 1 -- it is a count, not a rate.', 'count', 'patient', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_art_late_initiation', 'metric', 'Late ART initiation (ART.5 numerator)', 'ART initiations in the reporting month with a baseline CD4 count below 200 cells/mm3.', 'COUNT of clients with an ART start date in the reporting period, a baseline CD4 count test in the same month, and a baseline CD4 count below 200 cells/mm3', null, 'tamanu', 'WHO_SMART_HIV', 'ART.5', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.31 (ART.5). Late initiation is this count over who_dak_hiv_art_cd4_at_initiation -- advanced HIV disease at the point treatment starts, which is a measure of how late people are being diagnosed.', 'count', 'patient', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_art_on_art', 'metric', 'People living with HIV on ART (ART.1)', 'People living with HIV recorded as on antiretroviral therapy at the end of the reporting month.', 'COUNT of clients whose last recorded state at the reporting period end date is on ART. A point-in-time count, so a client not seen during the month is still counted -- the record says they are on treatment until it says otherwise', 'Not registered: Annex C''s denominators are the estimated number of people living with HIV, or the estimate of those who know their status, both of which come from outside Tamanu', 'tamanu', 'WHO_SMART_HIV', 'ART.1', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.27 (ART.1, "People living with HIV on ART") -- the second 95 of the UNAIDS targets, and the count a treatment coverage figure divides by a population estimate. Also serves as ART.9''s denominator, which Annex C words as clients on ART within the reporting period.', 'count', 'patient', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_art_on_art_key_population', 'metric', 'People living with HIV on ART, by key population (ART.1)', 'ART.1 disaggregated by key population: one row per client per key population they are recorded as belonging to.', 'COUNT of client-population pairs where the client''s last recorded state at the reporting period end date is on ART. Key population is a MultiSelect, so a client belonging to two populations contributes to both -- summing across populations therefore double-counts that client, which is what Annex C''s own disaggregation does', null, 'tamanu', 'WHO_SMART_HIV', 'ART.1', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.27 (ART.1), whose disaggregation list includes key population member type. Registered separately from who_dak_hiv_art_on_art rather than added to it as a column, because one client can hold several populations and a column would make the plain count of people wrong. The same bridge disaggregates any other indicator that needs it.', 'count', 'patient', 'facility_id,sex,key_population', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_art_routine_viral_load', 'metric', 'Routine viral load tests among established ART patients (ART.3 denominator)', 'Routine viral load samples collected in the reporting month from clients on ART for at least six months.', 'COUNT of clients on ART whose ART start date is more than six months before the end of the reporting period, with a viral load sample collected in the period for reason ''Routine viral load test''', null, 'tamanu', 'WHO_SMART_HIV', 'ART.3', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.29 (ART.3, "People living with HIV on ART who have suppressed viral load"). The six-month and routine-reason conditions are Annex C''s, not a local narrowing: a targeted test taken because treatment is failing would bias suppression downwards.', 'count', 'patient', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_art_toxicity', 'metric', 'Treatment-limiting ARV toxicity (ART.9 numerator)', 'Clients whose ART was stopped or whose regimen was substituted for toxicity during the reporting month.', 'COUNT of clients with a date ART stopped in the reporting period for reason toxicity or side effects, plus clients on ART with a first-, second- or third-line regimen substitution date in the period for the same reason. A client with both counts once', null, 'tamanu', 'WHO_SMART_HIV', 'ART.9', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.35 (ART.9, "ARV toxicity prevalence"). Prevalence is this count over who_dak_hiv_art_on_art, which is Annex C''s denominator of clients on ART within the reporting period.', 'count', 'patient', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_art_viral_suppression', 'metric', 'Viral suppression on ART (ART.3 numerator)', 'Clients on ART for at least six months whose routine viral load in the reporting month was below 1000 copies/mL.', 'COUNT of clients meeting who_dak_hiv_art_routine_viral_load whose viral load test result is below 1000 copies/mL', null, 'tamanu', 'WHO_SMART_HIV', 'ART.3', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.29 (ART.3). Suppression is this count over who_dak_hiv_art_routine_viral_load -- the third 95 of the UNAIDS targets.', 'count', 'patient', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_dsd_eligible', 'metric', 'Clients assessed as eligible for DSD ART (DSD.3 denominator)', 'Clients on ART assessed during the reporting month as eligible for a differentiated service delivery ART model.', 'COUNT of clients on ART with a date DSD ART eligibility assessed in the reporting period and eligible for DSD ART recorded true', null, 'tamanu', 'WHO_SMART_HIV', 'DSD.3', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.55 (DSD.3, "Coverage of DSD ART models among people living with HIV on ART"). Annex C offers two denominators -- those assessed eligible where an electronic system records the assessment, or all clients on ART where records are paper-based. This is the first, which is the one a Tamanu deployment has.', 'count', 'patient', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_dsd_enrolled', 'metric', 'Clients enrolled in a DSD ART model (DSD.3 numerator)', 'Clients on ART recorded during the reporting month as currently enrolled in a DSD ART model.', 'COUNT of clients on ART with currently enrolled in DSD ART model recorded true. Annex C gives this numerator no date element, so the submission recording the enrolment places it in a period', null, 'tamanu', 'WHO_SMART_HIV', 'DSD.3', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.55 (DSD.3). Coverage is this count over who_dak_hiv_dsd_eligible.', 'count', 'patient', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_dsd_retained', 'metric', 'Retention in DSD ART models (DSD.4 numerator)', 'Clients still enrolled in a differentiated service delivery model twelve or more months after starting it.', 'COUNT of clients meeting who_dak_hiv_dsd_retention_eligible whose last recorded state is enrolled in a DSD ART model', null, 'tamanu', 'WHO_SMART_HIV', 'DSD.4', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.56 (DSD.4). Retention is this count over who_dak_hiv_dsd_retention_eligible, at whichever months_on_dsd cohort the consumer selects.', 'count', 'patient', 'facility_id,sex,months_on_dsd', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_dsd_retention_eligible', 'metric', 'Clients due for DSD retention reporting (DSD.4 denominator)', 'Clients on ART whose differentiated service delivery model started at least twelve months before the end of the reporting month.', 'COUNT of clients on ART at the reporting period end date whose DSD ART start date is twelve or more months earlier. Annex C reports retention at 12, 24, 36, 48 and 60 months; months_on_dsd is emitted so a consumer selects the cohort rather than the model carrying five near-identical metrics', null, 'tamanu', 'WHO_SMART_HIV', 'DSD.4', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.56 (DSD.4, "Retention in DSD ART models").', 'count', 'patient', 'facility_id,sex,months_on_dsd', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_hts_client_positive', 'metric', 'Clients testing HIV-positive (HTS.3 numerator)', 'Clients whose HIV test in the reporting month returned a positive result.', 'COUNT of clients with HIV test result ''HIV-positive'', an HIV test date in the reporting period, and either a date HIV test results returned or an HIV diagnosis date in the reporting period', null, 'tamanu', 'WHO_SMART_HIV', 'HTS.3', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.20 (HTS.3). Positivity is this count over who_dak_hiv_hts_client_tested.', 'count', 'patient', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_hts_client_tested', 'metric', 'Clients tested for HIV (HTS.3 denominator)', 'Clients who received an HIV test result during the reporting month.', 'COUNT of clients with an HIV test date and a date HIV test results returned in the reporting period', null, 'tamanu', 'WHO_SMART_HIV', 'HTS.3', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.20 (HTS.3, "Individuals testing positive for HIV").', 'count', 'patient', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_hts_test', 'metric', 'HIV tests with results returned (HTS.2 denominator)', 'HIV tests performed whose results were returned to the client during the reporting month.', 'COUNT of tests with an HIV test date and a date HIV test results returned in the reporting period. Test grain, not client grain: Annex C counts tests here, so a client tested twice contributes twice', null, 'tamanu', 'WHO_SMART_HIV', 'HTS.2', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.19 (HTS.2, "HTS test volume and positivity"), read against the DAK data elements HIV.B.DE110 and HIV.B.DE60 as the generated who-dak-hiv forms collect them.', 'count', 'test', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md'),
        ('who_dak_hiv_hts_test_positive', 'metric', 'HIV-positive results returned (HTS.2 numerator)', 'HIV tests returning a positive result during the reporting month.', 'COUNT of tests with HIV test result ''HIV-positive'' and either a date HIV test results returned or an HIV diagnosis date in the reporting period', null, 'tamanu', 'WHO_SMART_HIV', 'HTS.2', 'WHO SMART guidelines HIV DAK, Web Annex C indicator HIV.IND.19 (HTS.2). Positivity is this count over who_dak_hiv_hts_test.', 'count', 'test', 'facility_id,sex', null, 'bes-maui', 'approved', 'specs/dbt-model/metric__who_dak_hiv_indicators.md')
) as md (
